template:
% 参数由系统自动注入；矩形：四角为直角，对角线相等且互相平分
% 视觉归一化：把较长的一边缩放到 6 个坐标单位，线宽字体不缩放；装饰尺寸已做 figscale 补偿
\pgfmathsetmacro{\figscale}{6 / max(\ab, \ad)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (A) at (0,0);
  \coordinate (B) at (\ab,0);
  \coordinate (C) at (\ab,\ad);
  \coordinate (D) at (0,\ad);
  \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
  % ∠A 直角记号
  \ifnum\rightmark>0
    \pgfmathsetmacro{\rm}{min(0.3/\figscale, \ab*0.2, \ad*0.2)}
    \draw[thick] (\rm,0) -- (\rm,\rm) -- (0,\rm);
  \fi
  % 对角线与交点 O（标签按宽高比放干净扇区：宽→正下、高→正右，避开对角线）
  \ifnum\showdiag>0
    \draw[thick] (A) -- (C);
    \draw[thick] (B) -- (D);
    \fill (\ab/2,\ad/2) circle [radius=1.6pt];
    \ifdim\ab pt>\ad pt
      \node[below] at (\ab/2,{\ad/2 - 0.28/\figscale}) {$O$};
    \else
      \node[right] at ({\ab/2 + 0.28/\figscale},\ad/2) {$O$};
    \fi
  \fi
  % 顶点标签
  \node[below left=3pt] at (A) {$A$};
  \node[below right=3pt] at (B) {$B$};
  \node[above right=3pt] at (C) {$C$};
  \node[above left=3pt] at (D) {$D$};
\end{tikzpicture}
